= BattleFrontier_BattleTowerLobby_EventScript_ExplainLinkMultisChallenge
msgbox	Die MULTI-BATTLE-RÄUME des BATTLE TOWER sind Einrichtungen für MULTI-BATTLES mit einem Freund.Du musst dich mit deinem Freund über Wireless-Adapter oder ein Game Boy Advance Game Link-Kabel verbinden.Du musst dich mit deinem Freund zusammentun und zwei verschiedene Arten von POKéMON einsetzen.Es gibt viele MULTI-BATTLE-RÄUME im BATTLE TOWER für Team-Kämpfe.In einem MULTI-BATTLE-RAUM erwarten dich und deinen Freund sieben Tag-Teams zur Herausforderung.Wenn es euch gelingt, alle sieben Teams zu besiegen, erhaltet ihr Kampfpunkte.Beachte, dass du deine Herausforderung anders als bei anderen RÄUMEN nicht unterbrechen darfst.Hast du erst begonnen, musst du sieben MULTI-BATTLES in Folge ohne Unterbrechung bestreiten.
goto BattleFrontier_BattleTowerLobby_EventScript_AskEnterLinkMultisChallenge
end
= BattleFrontier_BattleTowerLobby_EventScript_MultisAttendant
lock
faceplayer
setvar VAR_FRONTIER_FACILITY FRONTIER_FACILITY_TOWER
clearflag FLAG_CHOSEN_MULTI_BATTLE_NPC_PARTNER
special SavePlayerParty
msgbox	Hier wird das Talent von TRAINERN auf die Probe gestellt!Willkommen im BATTLE TOWER!Ich bin dein Führer für die MULTI-BATTLE-RÄUME.
goto BattleFrontier_BattleTowerLobby_EventScript_AskEnterMultisChallenge
= BattleFrontier_BattleTowerLobby_EventScript_AskEnterMultisChallenge
msgbox	Möchtest du die Herausforderung im MULTI-BATTLE-RAUM annehmen?
waitmessage
multichoice 17 6 MULTI_CHALLENGEINFO FALSE
switch VAR_RESULT
case 0 BattleFrontier_BattleTowerLobby_EventScript_TryEnterMultisChallenge
case 1 BattleFrontier_BattleTowerLobby_EventScript_ExplainMultisChallenge
case 2 BattleFrontier_BattleTowerLobby_EventScript_CancelChallenge
case MULTI_B_PRESSED BattleFrontier_BattleTowerLobby_EventScript_CancelChallenge
goto BattleFrontier_BattleTowerLobby_EventScript_TryEnterMultisChallenge
= BattleFrontier_BattleTowerLobby_EventScript_TryEnterMultisChallenge
setvar VAR_FRONTIER_BATTLE_MODE FRONTIER_MODE_MULTIS
msgbox	Der BATTLE-RAUM bietet zwei Schwierigkeitsstufen: Level 50 und offenes Level. Welche wählst du?
waitmessage
multichoice 17 6 MULTI_LEVEL_MODE FALSE
switch VAR_RESULT
case FRONTIER_LVL_TENT BattleFrontier_BattleTowerLobby_EventScript_CancelChallenge
case MULTI_B_PRESSED BattleFrontier_BattleTowerLobby_EventScript_CancelChallenge
frontier_checkineligible
goto_if_eq VAR_0x8004 TRUE BattleFrontier_BattleTowerLobby_EventScript_NotEnoughValidMons
frontier_set FRONTIER_DATA_LVL_MODE VAR_RESULT
msgbox	Wähle nun bitte die zwei POKéMON aus, die antreten sollen.
fadescreen FADE_TO_BLACK
call BattleFrontier_EventScript_GetLvlMode
copyvar VAR_0x8004 VAR_RESULT
setvar VAR_0x8005 FRONTIER_MULTI_PARTY_SIZE
special ChoosePartyForBattleFrontier
goto_if_eq VAR_RESULT 0 BattleFrontier_BattleTowerLobby_EventScript_LoadPartyCancelChallenge
msgboxyesno	Before entering a BATTLE ROOM, your progress must be saved. Is that okay?
switch VAR_RESULT
case NO BattleFrontier_BattleTowerLobby_EventScript_LoadPartyCancelChallenge
case YES BattleFrontier_BattleTowerLobby_EventScript_SaveBeforeMultisChallenge
case MULTI_B_PRESSED BattleFrontier_BattleTowerLobby_EventScript_LoadPartyCancelChallenge
goto BattleFrontier_BattleTowerLobby_EventScript_SaveBeforeMultisChallenge
= BattleFrontier_BattleTowerLobby_EventScript_SaveBeforeMultisChallenge
frontier_set FRONTIER_DATA_SELECTED_MON_ORDER
setvar VAR_TEMP_CHALLENGE_STATUS 0
tower_init
tower_set TOWER_DATA_WIN_STREAK_ACTIVE TRUE
frontier_set FRONTIER_DATA_PAUSED FALSE
special LoadPlayerParty
closemessage
delay 2
call Common_EventScript_SaveGame
setvar VAR_TEMP_CHALLENGE_STATUS 255
goto_if_eq VAR_RESULT 0 BattleFrontier_BattleTowerLobby_EventScript_CancelChallengeSaveFailed
incrementgamestat GAME_STAT_ENTERED_BATTLE_TOWER
setvar VAR_BRAVO_TRAINER_BATTLE_TOWER_ON FALSE
goto BattleFrontier_BattleTowerLobby_EventScript_EnterElevator
end
= BattleFrontier_BattleTowerLobby_EventScript_ExplainMultisChallenge
msgbox	Die MULTI-BATTLE-RÄUME des BATTLE TOWER sind Einrichtungen für MULTI-BATTLES.Für MULTI-BATTLES musst du dich mit einem TRAINER im TOWER zusammentun und mit je zwei POKéMON antreten.Im TOWER gibt es einen Raum namens BATTLE-SALON, wo du andere TRAINER treffen kannst.Dort musst du einen TRAINER finden, der als dein Partner in MULTI-BATTLES fungiert.Habt ihr euch zusammengetan, werdet ihr zu einem MULTI-BATTLE-RAUM gebracht.Im MULTI-BATTLE-RAUM erwarten sieben Tag-Teams eure Herausforderung.Wenn es euch gelingt, alle sieben Teams zu besiegen, erhaltet ihr Kampfpunkte.Wenn du deine Herausforderung unterbrechen willst, speichere bitte das Spiel.Wenn du vor der Unterbrechung nicht speicherst, wirst du disqualifiziert.
goto BattleFrontier_BattleTowerLobby_EventScript_AskEnterMultisChallenge
end
